var cascadingSlotGameResult=function(){var t=document.querySelector("#result-container"),i=document.querySelector("template"),n=0;return{onInputNickname:function(n){n.preventDefault();n.currentTarget.value!==""&&$(".error").addClass("hidden")},addTumble:function(){$("#result-container").find(".add-tumble").remove();var r=i.content.cloneNode(!0);r.querySelector("span").textContent=n===0?"Base Spin":"Tumbling "+n;t.appendChild(r);n++},submit:function(n){var i,t,r;if(n.preventDefault(),i=[],$(".result-temp").each(function(){var n=$(this).find(".result-raw").val();n!==""&&i.push({Name:$(this).find(".attempt").text(),Value:n})}),t=$("#Nickname").val(),t===undefined||t===""){$(".error").removeClass("hidden");return}r={roundName:t,rawResults:i,gameConfigName:$("#GameName").val()};$.ajax({type:"POST",url:"SetCascadingSlotResult",data:r,dataType:"html",success:function(n){$("#set-result").html(n)}})}}}();$(document).ready(function(){cascadingSlotGameResult.addTumble()});